import type { Writable } from 'node:stream';
import type { ImageStreamMetadata } from '../lib/Image';
export type RegisterImageEvent = {
    args: void;
    return: {
        id: string;
        url: string;
        localUrl: string | null;
        cloudUrl: string | null;
    };
};
export type UnregisterImageEvent = {
    args: {
        id: string;
    };
    return: void;
};
export type UpdateImageEvent = {
    args: {
        id: string;
        args?: Record<string, unknown>;
    };
    return: void;
};
export type SDKPipeEvent = {
    args: {
        id: string;
        args: Writable;
    };
    return: ImageStreamMetadata;
};
export type HomeyPipeEvent = {
    args: {
        id: string;
        stream: Writable;
    };
    return: ImageStreamMetadata;
};
export type HomeyImageEvents = {
    pipe: HomeyPipeEvent;
};
export type SDKImageEvents = {
    registerImage: RegisterImageEvent;
    unregisterImage: UnregisterImageEvent;
    update: UpdateImageEvent;
    pipe: SDKPipeEvent;
};
export type ImageClient = {
    emit: (event: keyof SDKImageEvents, args?: unknown) => Promise<unknown>;
};
